import { asNullableRecord as asRecord } from "@openclaw/normalization-core/record-coerce";
import type { GatewayBrowserClient } from "../../api/gateway.ts";
import { hasOperatorReadAccess } from "../../app/operator-access.ts";
import { summarizeMcpServers } from "../../lib/config/mcp-servers.ts";
import type { SessionToolOverrides } from "../../lib/sessions/patch.ts";
import { readOwnEntry } from "../../lib/sessions/tool-overrides.ts";
import { loadSkillStatusReport } from "../../lib/skills/status-report.ts";
import type {
  ChatComposerCapabilityMenuProps,
  ChatComposerMenuSkill,
} from "./composer-capability-types.ts";

export function composerMcpServers(
  config: Record<string, unknown> | null,
  options: { auth: GatewayBrowserClient["auth"]; loading: boolean },
): Pick<ChatComposerCapabilityMenuProps, "mcpServers" | "mcpServersReadState"> {
  const mcpServersReadState = !hasOperatorReadAccess(options.auth)
    ? "restricted"
    : config !== null
      ? "ready"
      : options.loading
        ? "loading"
        : "unavailable";
  return {
    mcpServers: mcpServersReadState === "ready" ? (summarizeMcpServers(config) ?? []) : [],
    mcpServersReadState,
  };
}

export function composerWebSearchBaseEnabled(config: Record<string, unknown> | null): boolean {
  return asRecord(asRecord(asRecord(config?.tools)?.web)?.search)?.enabled !== false;
}

export function resolveComposerSkills(
  skills: readonly ChatComposerMenuSkill[] | null,
  toolOverrides: SessionToolOverrides | null | undefined,
) {
  return (
    skills?.map((skill) => ({
      ...skill,
      enabled:
        skill.missingDeps || skill.blocked
          ? false
          : (readOwnEntry(toolOverrides?.skills, skill.key) ?? skill.baseEnabled),
    })) ?? null
  );
}

export class ComposerSkillCatalog {
  private readonly skills = new Map<string, ChatComposerMenuSkill[]>();
  private readonly loading = new Set<string>();
  private readonly reads = new Map<string, Promise<readonly ChatComposerMenuSkill[] | null>>();
  private client: GatewayBrowserClient | null = null;
  private connectionEpoch: number | undefined;

  constructor(private readonly notify: () => void) {}

  synchronize(client: GatewayBrowserClient | null, connectionEpoch: number | undefined) {
    if (this.client === client && this.connectionEpoch === connectionEpoch) {
      return;
    }
    this.client = client;
    this.connectionEpoch = connectionEpoch;
    this.skills.clear();
    this.loading.clear();
    this.reads.clear();
  }

  load(
    client: GatewayBrowserClient | null,
    connectionEpoch: number | undefined,
    agentId: string,
    isCurrentConnection: () => boolean,
  ): void {
    this.synchronize(client, connectionEpoch);
    if (
      !client ||
      !isCurrentConnection() ||
      this.skills.has(agentId) ||
      this.loading.has(agentId)
    ) {
      return;
    }
    const isCurrent = () =>
      this.client === client && this.connectionEpoch === connectionEpoch && isCurrentConnection();
    this.loading.add(agentId);
    const read = loadSkillStatusReport(client, agentId)
      .then((report) => {
        if (!isCurrent()) {
          return null;
        }
        const skills =
          report?.skills
            .map((skill): ChatComposerMenuSkill => {
              const missingDeps = Object.values(skill.missing).some((values) => values.length > 0);
              const blocked = skill.blockedByAllowlist || skill.blockedByAgentFilter;
              const baseEnabled = !skill.disabled;
              return {
                key: skill.skillKey,
                name: skill.name,
                emoji: skill.emoji,
                enabled: baseEnabled && !missingDeps && !blocked,
                baseEnabled,
                ...(missingDeps ? { missingDeps: true } : {}),
                ...(blocked ? { blocked: true } : {}),
              };
            })
            .toSorted((left, right) => left.name.localeCompare(right.name)) ?? null;
        if (skills) {
          this.skills.set(agentId, skills);
        }
        return skills;
      })
      .catch((error: unknown) => {
        if (isCurrent()) {
          throw error;
        }
        return null;
      })
      .finally(() => {
        if (isCurrent()) {
          this.loading.delete(agentId);
          this.notify();
        }
      });
    this.reads.set(agentId, read);
    // The menu opens before a renderer observes this admitted read.
    void read.catch(() => undefined);
    this.notify();
  }

  read(agentId: string) {
    return this.reads.get(agentId) ?? null;
  }

  rows(agentId: string, toolOverrides: SessionToolOverrides | null | undefined) {
    return resolveComposerSkills(this.skills.get(agentId) ?? null, toolOverrides);
  }
}
